-- Written by the original application (last known-good release) at commit a03c887dd76056695f81e55d0ff1cac4315ee444.
CREATE TABLE bom_components (
	id INTEGER NOT NULL, 
	parent_part_id INTEGER NOT NULL, 
	component_part_id INTEGER NOT NULL, 
	quantity_per INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_bom_components_parent_component UNIQUE (parent_part_id, component_part_id), 
	FOREIGN KEY(parent_part_id) REFERENCES parts (id), 
	FOREIGN KEY(component_part_id) REFERENCES parts (id)
);
