CREATE TABLE lots (
	id INTEGER NOT NULL, 
	part_id INTEGER NOT NULL, 
	lot_number VARCHAR NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at VARCHAR NOT NULL, 
	notes TEXT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_lots_part_lot UNIQUE (part_id, lot_number), 
	FOREIGN KEY(part_id) REFERENCES parts (id)
);
